package com.citacloud.springboot.contacloud.app.models;import jakarta.persistence.*;import java.math.BigDecimal;import java.time.OffsetDateTime;import java.util.UUID;
@Entity @Table(name="sales_surcharge_authorization") public class AutorizacionRecargoVenta {@Id @GeneratedValue(strategy=GenerationType.UUID)private UUID id;@Column(name="tenant_id",nullable=false)private UUID tenantId;@Column(name="empresa_id",nullable=false)private UUID empresaId;@Column(name="operation_key",nullable=false)private UUID operacionId;@Column(name="requested_by",nullable=false)private UUID solicitadaPor;@Column(name="authorized_by",nullable=false)private UUID autorizadaPor;@Column(name="requester_role_id",nullable=false)private UUID rolSolicitanteId;@Column(name="authorizer_role_id",nullable=false)private UUID rolAutorizadorId;@Enumerated(EnumType.STRING)@Column(name="scope",nullable=false)private AlcanceRecargoVenta alcance;@Enumerated(EnumType.STRING)@Column(name="surcharge_type",nullable=false)private TipoRecargoVenta tipo;@Column(name="concept_id",nullable=false)private UUID conceptoId;@Column(name="requested_value",nullable=false)private BigDecimal valor;@Column(name="eligible_base",nullable=false)private BigDecimal base;@Column(name="surcharge_amount",nullable=false)private BigDecimal monto;@Column(name="fingerprint",nullable=false)private String fingerprint;@Enumerated(EnumType.STRING)@Column(name="status",nullable=false)private EstadoAutorizacionRecargo estado=EstadoAutorizacionRecargo.AUTHORIZED;@Column(name="authorized_at",nullable=false,insertable=false,updatable=false)private OffsetDateTime autorizadaEn;@Column(name="consumed_at")private OffsetDateTime consumidaEn;@Column(name="sales_invoice_id")private UUID facturaId;protected AutorizacionRecargoVenta(){}public AutorizacionRecargoVenta(UUID t,UUID e,UUID op,UUID sp,UUID ap,UUID sr,UUID ar,AlcanceRecargoVenta al,TipoRecargoVenta ti,UUID co,BigDecimal v,BigDecimal b,BigDecimal m,String f){tenantId=t;empresaId=e;operacionId=op;solicitadaPor=sp;autorizadaPor=ap;rolSolicitanteId=sr;rolAutorizadorId=ar;alcance=al;tipo=ti;conceptoId=co;valor=v;base=b;monto=m;fingerprint=f;}public void consumir(UUID factura){if(estado!=EstadoAutorizacionRecargo.AUTHORIZED)throw new IllegalStateException();estado=EstadoAutorizacionRecargo.CONSUMED;facturaId=factura;consumidaEn=OffsetDateTime.now();}public UUID getId(){return id;}public UUID getOperacionId(){return operacionId;}public UUID getSolicitadaPor(){return solicitadaPor;}public UUID getAutorizadaPor(){return autorizadaPor;}public OffsetDateTime getAutorizadaEn(){return autorizadaEn;}public EstadoAutorizacionRecargo getEstado(){return estado;}public String getFingerprint(){return fingerprint;}}
